package cn.zhuatech.invoiceagent.controller;import cn.zhuatech.invoiceagent.common.ApiResponse;import cn.zhuatech.invoiceagent.service.InvoiceDuplicateRiskService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/enterprise/invoice")public class InvoiceDuplicateRiskController{private final InvoiceDuplicateRiskService service;public InvoiceDuplicateRiskController(InvoiceDuplicateRiskService s){service=s;}@PostMapping("/duplicate-risk")public ApiResponse<InvoiceDuplicateRiskService.Result>assess(@Valid@RequestBody InvoiceDuplicateRiskService.Request r){return ApiResponse.ok("发票重复风险评估完成",service.assess(r));}}
